-- 昵称映射表：游戏ID → 联盟昵称，识别/导入时自动认领，避免人工改ID
CREATE TABLE "nick_aliases" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "nick_aliases_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"alias" text NOT NULL,
	"nickname" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "nick_aliases_alias_check" CHECK (char_length(btrim("alias")) BETWEEN 1 AND 80),
	CONSTRAINT "nick_aliases_nickname_check" CHECK (char_length(btrim("nickname")) BETWEEN 1 AND 80)
);
--> statement-breakpoint
CREATE UNIQUE INDEX "nick_aliases_alias_idx" ON "nick_aliases" ("alias");--> statement-breakpoint
